#!/usr/bin/env bash
# init_flags.sh — generate per-build opaque flag tokens for power-lab
# (runtime-only, not committed in source). Mirrors network-chain
# flags/init_flags.sh. Writes a .env the compose stack reads.
# Run once before `docker compose up`. Re-run to rotate.
set -euo pipefail
cd "$(dirname "$0")/.."

rand() { head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n'; }

MID="CTF{blackbox_optics_mid_$(rand)}"
HARD="CTF{reactor_scram_hard_$(rand)}"
AGENT="CTF{agent_obfuscated_hard_$(rand)}"

cat > .env <<EOF
# generated by flags/init_flags.sh — do not commit
PWR_FLAG_MID=${MID}
PWR_FLAG_HARD=${HARD}
PWR_FLAG_AGENT=${AGENT}
PWR_RUN_DIR=/var/run/power
EOF

echo "wrote .env with fresh PWR flags."
echo "  mid   (blackbox optics) : ${MID}"
echo "  hard  (reactor scram)   : ${HARD}"
echo "  agent (firmware RE)     : ${AGENT}"
echo "SSH entry stays static (predictable-password vuln):"
echo "  ssh default@localhost -p 2222  # password: PWR-3001-STAT"
echo "  (then predict officer password PWR-3002-STAT and: su officer)"
